BRESENHAM’S LINE GENERATION ALGORITHM */
#include<graphics.h>
#include<stdio.h>
#include<math.h>
#include<conio.h>
void main()
{
int xa, ya, xb, yb;
int dx, dy;
int x, y;
int p;
int i;
int signx, signy;
int gd = DETECT,gm;
initgraph(&gd, &gm,"c: \\tc\\bgi");
printf("enter start point coordinate");
scanf("%d%d", &xa, &ya);
printf("enter end point coordinate");
scanf("%d%d", &xb, &yb);
dx = xb − xa;
dy = yb − ya;
x = xa;
y = ya;
if (dx > = 0)
signx = +1;
else
signx = −1;
if (dy > = 0)
signy = +1;
else
signy = −1;
if (abs(dy) < abs(dx))
{
p = (2 * dy * signy) − (dx * signx);
for (i = 0; i < = dx * signx; i++)
{
putpixel(floor(x),floor(y),RED);
if (p < 0)
{
x = x + signx;
y = y;
p = p + (2 * dy * signy);
}
else
{
x = x + signx;
y = y + signy;
p = p + (2 * dy * signy) − (2 * dx * signx);
}
}
}
else
{
p = (2 * dx * signx − dy * signy);
for( i =0; i < = dy * signy; i++)
{
putpixel(floor(x),floor(y),RED);
if (p < 0)
{
x = x;
y = y + signy;
p = p + 2 * dx * signx;
}
else
{
x=x+signx;
y=y+signy;
p=p+(2*dx*signx)-(2*dy* signy);
}
}
}
getch();
}
